'use strict';

// Real PKI testing — the test mock server presents a cert issued by a
// dedicated CA at tests/certs/ca.crt (generated by test-helpers.js
// generateTestCerts() with SAN DNS:localhost,IP:127.0.0.1). We trust
// that CA via NODE_EXTRA_CA_CERTS so the production b.httpClient TLS
// handshake validates normally — same trust path users see in
// production, no rejectUnauthorized hacks.
//
// NODE_EXTRA_CA_CERTS is read by Node when it boots the default TLS
// SecureContext, which is too early for an in-process `process.env`
// assignment to take effect. The bootstrap below ensures the cert
// files exist, then re-executes the test file with the env var set in
// the child's environment so the child's Node sees the trust extension
// from initialization. The recursion guard (HS_TEST_CA_TRUSTED) keeps
// us from forking forever.
(function bootstrapTestCa() {
  if (process.env.HS_TEST_CA_TRUSTED === '1') return;

  const fs = require('node:fs');
  const path = require('node:path');
  const { execFileSync, spawnSync } = require('node:child_process');
  const certsDir = path.join(__dirname, 'certs');
  const caCertPath = path.join(certsDir, 'ca.crt');
  const caKeyPath = path.join(certsDir, 'ca.key');
  const serverCertPath = path.join(certsDir, 'server.crt');
  const serverKeyPath = path.join(certsDir, 'server.key');

  // Regenerate the test PKI when a cert file is missing OR the cached cert is
  // expired / within 24h of expiry. Certs are issued for 10 years below, so in
  // practice this only fires on a fresh checkout — but the expiry check
  // self-heals a stale short-lived cert from an older revision instead of
  // failing every run with "certificate has expired" until it's deleted by hand.
  function _needsRegen() {
    if (!fs.existsSync(caCertPath) || !fs.existsSync(caKeyPath) ||
        !fs.existsSync(serverCertPath) || !fs.existsSync(serverKeyPath)) return true;
    try {
      var nodeCrypto = require('node:crypto');
      var soon = Date.now() + 24 * 60 * 60 * 1000;
      var srv = new nodeCrypto.X509Certificate(fs.readFileSync(serverCertPath));
      var ca = new nodeCrypto.X509Certificate(fs.readFileSync(caCertPath));
      return Date.parse(srv.validTo) < soon || Date.parse(ca.validTo) < soon;
    } catch (_e) { return true; }
  }
  if (_needsRegen()) {
    fs.mkdirSync(certsDir, { recursive: true });
    const extFile = path.join(certsDir, 'server.ext');
    const serverCsrPath = path.join(certsDir, 'server.csr');
    try {
      execFileSync('openssl', ['ecparam', '-genkey', '-name', 'secp384r1', '-noout', '-out', caKeyPath], { stdio: 'pipe' });
      execFileSync('openssl', ['req', '-new', '-x509', '-key', caKeyPath, '-out', caCertPath, '-days', '3650', '-subj', '/CN=HermitStash Test CA/O=HermitStash Test'], { stdio: 'pipe' });
      fs.writeFileSync(extFile, 'subjectAltName=DNS:localhost,IP:127.0.0.1\nbasicConstraints=CA:FALSE\nkeyUsage=digitalSignature,keyEncipherment\nextendedKeyUsage=serverAuth\n');
      execFileSync('openssl', ['ecparam', '-genkey', '-name', 'secp384r1', '-noout', '-out', serverKeyPath], { stdio: 'pipe' });
      execFileSync('openssl', ['req', '-new', '-key', serverKeyPath, '-out', serverCsrPath, '-subj', '/CN=localhost/O=HermitStash Test Server'], { stdio: 'pipe' });
      execFileSync('openssl', ['x509', '-req', '-in', serverCsrPath, '-CA', caCertPath, '-CAkey', caKeyPath, '-CAcreateserial', '-out', serverCertPath, '-days', '3650', '-extfile', extFile], { stdio: 'pipe' });
      try { fs.unlinkSync(serverCsrPath); } catch {}
      try { fs.unlinkSync(extFile); } catch {}
      try { fs.unlinkSync(path.join(certsDir, 'ca.srl')); } catch {}
    } catch (e) {
      console.error('[test-autoupdate] Failed to bootstrap test PKI:', e.message);
      console.error('  install OpenSSL (https://wiki.openssl.org/) and re-run');
      process.exit(1);
    }
  }

  const childEnv = Object.assign({}, process.env, {
    NODE_EXTRA_CA_CERTS: caCertPath,
    HS_TEST_CA_TRUSTED: '1',
  });
  const r = spawnSync(process.execPath, [__filename, ...process.argv.slice(2)], {
    stdio: 'inherit',
    env: childEnv,
  });
  process.exit(r.status === null ? 1 : r.status);
})();

// E2E tests for lib/updater.js (b.selfUpdate-backed).
//
// These tests do NOT need the HermitStash server — they mount a tiny mock
// HTTPS server that mimics the shape of github.com's /releases/latest JSON
// plus the asset downloads, and exercise the production updater code via
// createUpdater(opts).
//
// Signature format (v0.7.7+): ECDSA P-384 over the binary directly with
// SHA3-512 hash + DER encoding — what `crypto.createSign('sha3-512').
// update(binary).end().sign({ key, dsaEncoding: 'der' })` produces and
// what `scripts/standalone-verifier.js` checks. Daemon-side verification
// in `lib/updater.js` routes through the same standalone verifier; the
// framework's `b.selfUpdate.verify` cannot be used because it infers
// SHA-384 from the P-384 curve and rejects SHA3-512 sigs.
//
// The signing private key is at tests/autoupdate-signing.key (gitignored).
// The test discovers it at module load; if missing, the tests are skipped.

const { describe, it, before, after } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const crypto = require('node:crypto');
const https = require('node:https');
const http2 = require('node:http2');
const { createUpdater, compareVersions, assetName } = require('../lib/updater');

const SIGNING_KEY_PATH = path.join(__dirname, 'autoupdate-signing.key');
const SERVER_CERT = fs.readFileSync(path.join(__dirname, 'certs', 'server.crt'));
const SERVER_KEY = fs.readFileSync(path.join(__dirname, 'certs', 'server.key'));

const HAS_KEY = fs.existsSync(SIGNING_KEY_PATH);
const SIGNING_KEY_PEM = HAS_KEY ? fs.readFileSync(SIGNING_KEY_PATH, 'utf8') : null;
const PUBKEY_PEM = HAS_KEY
  ? crypto.createPublicKey(SIGNING_KEY_PEM).export({ type: 'spki', format: 'pem' })
  : null;

const ROGUE_KEYPAIR = crypto.generateKeyPairSync('ec', { namedCurve: 'P-384' });
const ROGUE_KEY = ROGUE_KEYPAIR.privateKey;

// New signing format: ECDSA P-384 + SHA3-512, DER encoding. Matches
// what scripts/release.sh + .github/workflows/release.yml produce after
// v0.7.7's SHA3-512 pin.
function signBinary(binary, privateKey) {
  const signer = crypto.createSign('sha3-512');
  signer.update(binary);
  signer.end();
  return signer.sign({ key: privateKey, dsaEncoding: 'der' });
}

function platformTag() {
  const p = process.platform;
  return p === 'win32' ? 'win' : p === 'darwin' ? 'macos' : 'linux';
}

function makeAssetName(version) {
  const ext = process.platform === 'win32' ? '.exe' : '';
  return `hermitstash-sync-v${version}-${platformTag()}-${process.arch}${ext}`;
}

function createMockServer(state) {
  // The production path makes BOTH h2 and h1 calls: b.selfUpdate.poll
  // passes no agent and ends up on b.httpClient's h2-via-ALPN
  // transport; lib/updater.js's downloadTo passes our PQC https.Agent
  // which b.httpClient honors as an h1-only escape hatch (see
  // http-client.js:1030). The mock has to serve both.
  //
  // Rather than register both 'stream' (h2) and 'request' (h1)
  // listeners — which race in Node's http2 compat layer because
  // 'request' ALSO fires for h2 streams as a backward-compat shim,
  // throwing ERR_HTTP2_HEADERS_SENT on the second write — we register
  // only 'request'. The compat layer dispatches h2 streams through
  // 'request' too, so one listener cleanly handles both transports.
  const tlsOpts = {
    cert: SERVER_CERT,
    key: SERVER_KEY,
    ALPNProtocols: ['h2', 'http/1.1'],
    allowHTTP1: true,
  };
  const server = http2.createSecureServer(tlsOpts);

  function handle(reqPath, send) {
    if (state.statusOverride && state.statusOverride[reqPath]) {
      send(state.statusOverride[reqPath]);
      return;
    }
    if (reqPath.endsWith('/releases/latest')) {
      const port = server.address().port;
      const assets = Object.keys(state.assets).map(name => ({
        name,
        browser_download_url: `https://127.0.0.1:${port}/download/${encodeURIComponent(name)}`,
      }));
      send(200, JSON.stringify({ tag_name: `v${state.version}`, assets }), 'application/json');
      return;
    }
    if (reqPath.startsWith('/download/')) {
      const name = decodeURIComponent(reqPath.slice('/download/'.length));
      const asset = state.assets[name];
      if (!asset) { send(404); return; }
      send(200, asset.body, asset.contentType || 'application/octet-stream');
      return;
    }
    send(404);
  }

  server.on('request', (req, res) => {
    const url = new URL(req.url, 'https://127.0.0.1');
    handle(url.pathname, (status, body, contentType) => {
      // Guard: in http2-compat mode the response stream can be torn down
      // by GOAWAY (e.g. server.close() during a keep-alive teardown)
      // between event dispatch and our send. Writing to a destroyed/
      // committed Http2ServerResponse throws ERR_HTTP2_HEADERS_SENT and
      // surfaces as an async-leak warning attributed to the most recent
      // before/after hook. Skip the write when the response is no longer
      // writable.
      if (res.headersSent || res.writableEnded || res.destroyed) return;
      try {
        res.statusCode = status;
        if (contentType) res.setHeader('Content-Type', contentType);
        res.end(body);
      } catch (_e) { /* response committed mid-write — drop */ }
    });
  });

  return server;
}

function startServerAsync(server) {
  return new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', () => resolve(server.address().port));
  });
}

function stopServerAsync(server) {
  return new Promise(resolve => server.close(() => resolve()));
}

function buildReleaseState(version, binary, signer = SIGNING_KEY_PEM) {
  const name = makeAssetName(version);
  const sig = signBinary(binary, signer);
  return {
    version,
    assets: {
      [name]: { body: binary },
      [`${name}.sig`]: { body: sig },
    },
  };
}

function tempDir(label) {
  return fs.mkdtempSync(path.join(os.tmpdir(), `hs-updater-${label}-`));
}

describe('Auto-update — signature verification', { timeout: 20000 }, () => {

  if (!HAS_KEY) {
    it.skip('signing key missing at tests/autoupdate-signing.key — skipping suite');
    return;
  }

  let server;
  let port;
  let state;

  before(async () => {
    state = buildReleaseState('9.9.9', Buffer.from('fake binary payload v9.9.9'));
    server = createMockServer(state);
    port = await startServerAsync(server);
  });

  after(async () => { await stopServerAsync(server); });

  function mkUpdater(overrides = {}) {
    const execDir = tempDir('exec');
    const currentPath = path.join(execDir, process.platform === 'win32' ? 'hs.exe' : 'hs');
    fs.writeFileSync(currentPath, 'OLD BINARY', { mode: 0o755 });
    return createUpdater({
      currentVersion: '0.4.6',
      pubkeyPem: PUBKEY_PEM,
      apiBase: `https://127.0.0.1:${port}`,
      httpsAgent: new https.Agent({ keepAlive: true }),
      isSeaBinary: () => true,
      pollMs: 60_000,
      initialDelayMs: 0,
      probationMs: 1000,
      markerPath: path.join(tempDir('marker'), 'update-pending.json'),
      getExecPath: () => currentPath,
      getArgv: () => [],
      exitFn: () => {},
      spawnFn: () => ({ unref() {} }),
      ...overrides,
    });
  }

  it('happy path: finds newer release, verifies signature, hands off install', async () => {
    let installed = false;
    const up = mkUpdater();
    const result = await up.checkOnce(async (install) => { installed = true; await install(); });
    assert.equal(result.status, 'ready', `expected ready, got ${result.status}${result.error ? ': '+result.error.message : ''}`);
    assert.equal(result.version, '9.9.9');
    assert.ok(installed, 'install hand-off should have been called');
  });

  it('rejects update when signature is from an unauthorized key', async () => {
    const binary = Buffer.from('fake binary payload v9.9.9');
    const name = makeAssetName('9.9.9');
    const rogueSig = signBinary(binary, ROGUE_KEY);
    const rogueState = {
      version: '9.9.9',
      assets: {
        [name]: { body: binary },
        [`${name}.sig`]: { body: rogueSig },
      },
    };
    await swapState(rogueState, async () => {
      const up = mkUpdater();
      const result = await up.checkOnce();
      assert.equal(result.status, 'error');
      assert.match(result.error.message, /signature/i);
    });
  });

  it('rejects update when binary bytes are tampered after signing', async () => {
    const realBinary = Buffer.from('fake binary payload v9.9.9');
    const sig = signBinary(realBinary, SIGNING_KEY_PEM);
    const tamperedBinary = Buffer.from('TAMPERED binary payload v9.9.9');
    const name = makeAssetName('9.9.9');
    const tamperedState = {
      version: '9.9.9',
      assets: {
        [name]: { body: tamperedBinary },
        [`${name}.sig`]: { body: sig },
      },
    };
    await swapState(tamperedState, async () => {
      const up = mkUpdater();
      const result = await up.checkOnce();
      assert.equal(result.status, 'error');
      assert.match(result.error.message, /signature/i);
    });
  });

  it('same version: reports up-to-date, does not download', async () => {
    const up = mkUpdater({ currentVersion: '9.9.9' });
    const result = await up.checkOnce();
    assert.equal(result.status, 'up-to-date');
  });

  it('older version on server: reports up-to-date', async () => {
    const up = mkUpdater({ currentVersion: '99.0.0' });
    const result = await up.checkOnce();
    assert.equal(result.status, 'up-to-date');
  });

  it('source install: reports source-notify without downloading binary', async () => {
    const up = mkUpdater({ isSeaBinary: () => false });
    const result = await up.checkOnce();
    assert.equal(result.status, 'source-notify');
    assert.equal(result.version, '9.9.9');
  });

  it('no pubkey embedded: disables auto-update entirely', async () => {
    const up = mkUpdater({ pubkeyPem: null });
    const result = await up.checkOnce();
    assert.equal(result.status, 'disabled');
  });

  it('missing .sig asset: fails with clear message', async () => {
    const binary = Buffer.from('fake binary payload v9.9.9');
    const name = makeAssetName('9.9.9');
    const partial = {
      version: '9.9.9',
      assets: {
        [name]: { body: binary },
        // .sig intentionally missing
      },
    };
    await swapState(partial, async () => {
      const up = mkUpdater();
      const result = await up.checkOnce();
      assert.equal(result.status, 'error');
      assert.match(result.error.message, /Missing.*sig/i);
    });
  });

  async function swapState(newState, fn) {
    const saved = { version: state.version, assets: state.assets };
    state.version = newState.version;
    state.assets = newState.assets;
    try { await fn(); } finally {
      state.version = saved.version;
      state.assets = saved.assets;
    }
  }
});

describe('Auto-update — install and swap', { timeout: 20000 }, () => {

  if (!HAS_KEY) {
    it.skip('signing key missing');
    return;
  }

  let server;
  let port;
  let state;

  before(async () => {
    state = buildReleaseState('9.9.9', Buffer.from('new binary v9.9.9'));
    server = createMockServer(state);
    port = await startServerAsync(server);
  });

  after(async () => { await stopServerAsync(server); });

  it('installs new binary, writes marker, copies old to .prev, spawns child', async () => {
    const execDir = tempDir('exec');
    const currentPath = path.join(execDir, process.platform === 'win32' ? 'hs.exe' : 'hs');
    fs.writeFileSync(currentPath, 'OLD BINARY CONTENTS', { mode: 0o755 });

    const markerPath = path.join(tempDir('marker'), 'update-pending.json');

    let spawnCalled = null;

    const up = createUpdater({
      currentVersion: '0.4.6',
      pubkeyPem: PUBKEY_PEM,
      apiBase: `https://127.0.0.1:${port}`,
      httpsAgent: new https.Agent({ keepAlive: true }),
      isSeaBinary: () => true,
      pollMs: 60_000,
      initialDelayMs: 0,
      probationMs: 2000,
      markerPath,
      getExecPath: () => currentPath,
      getArgv: () => ['start'],
      exitFn: () => {},
      spawnFn: (cmd, args, opts) => {
        spawnCalled = { cmd, args, opts };
        return { unref() {} };
      },
    });

    const result = await up.checkOnce(async (install) => { await install(); });

    assert.equal(result.status, 'ready');
    assert.ok(spawnCalled, 'install should have spawned the new binary');
    assert.equal(spawnCalled.cmd, currentPath);
    assert.deepEqual(spawnCalled.args, ['start']);

    const ext = process.platform === 'win32' ? '.exe' : '';
    const base = currentPath.slice(0, currentPath.length - ext.length);
    const prevPath = `${base}.prev${ext}`;

    assert.equal(fs.readFileSync(currentPath, 'utf8'), 'new binary v9.9.9');
    assert.equal(fs.readFileSync(prevPath, 'utf8'), 'OLD BINARY CONTENTS');

    const marker = JSON.parse(fs.readFileSync(markerPath, 'utf8'));
    assert.equal(marker.newVersion, '9.9.9');
    assert.equal(marker.prevBinaryPath, prevPath);
    assert.ok(marker.installedAt > 0);
  });
});

describe('Auto-update — rollback & probation', { timeout: 10000 }, () => {

  if (!HAS_KEY) {
    it.skip('signing key missing');
    return;
  }

  function mkRollbackUpdater({ currentVersion, markerPath, execPath, spawnCapture, exitCapture }) {
    return createUpdater({
      currentVersion,
      pubkeyPem: PUBKEY_PEM,
      pollMs: 60_000,
      initialDelayMs: 60_000,
      probationMs: 1000,
      markerPath,
      getExecPath: () => execPath,
      getArgv: () => [],
      isSeaBinary: () => true,
      httpsAgent: new https.Agent({ keepAlive: true }),
      spawnFn: (cmd, args, opts) => { spawnCapture.push({ cmd, args }); return { unref() {} }; },
      exitFn: (code) => { exitCapture.push(code); },
    });
  }

  it('no marker: returns no-marker', async () => {
    const markerPath = path.join(tempDir('rb'), 'update-pending.json');
    const spawns = []; const exits = [];
    const up = mkRollbackUpdater({
      currentVersion: '0.4.6',
      markerPath,
      execPath: path.join(tempDir('rb'), 'hs'),
      spawnCapture: spawns,
      exitCapture: exits,
    });
    assert.equal(await up.checkRollback(), 'no-marker');
    assert.equal(spawns.length, 0);
    assert.equal(exits.length, 0);
  });

  it('fresh marker within probation window: returns probation (no rollback)', async () => {
    const dir = tempDir('rb');
    const markerPath = path.join(dir, 'update-pending.json');
    const execPath = path.join(dir, 'hs');
    fs.writeFileSync(execPath, 'new', { mode: 0o755 });
    fs.writeFileSync(path.join(dir, 'hs.prev'), 'old', { mode: 0o755 });
    fs.writeFileSync(markerPath, JSON.stringify({
      newVersion: '9.9.9',
      prevBinaryPath: path.join(dir, 'hs.prev'),
      installedAt: Date.now(),
    }));

    const spawns = []; const exits = [];
    const up = mkRollbackUpdater({
      currentVersion: '9.9.9',
      markerPath,
      execPath,
      spawnCapture: spawns,
      exitCapture: exits,
    });
    assert.equal(await up.checkRollback(), 'probation');
    assert.equal(spawns.length, 0);
    assert.equal(exits.length, 0);
    assert.equal(fs.readFileSync(execPath, 'utf8'), 'new');
  });

  it('old marker past probation window: restores .prev, spawns, exits', async () => {
    const dir = tempDir('rb');
    const markerPath = path.join(dir, 'update-pending.json');
    const execPath = path.join(dir, 'hs');
    const prevPath = path.join(dir, 'hs.prev');
    fs.writeFileSync(execPath, 'BROKEN NEW', { mode: 0o755 });
    fs.writeFileSync(prevPath, 'GOOD OLD', { mode: 0o755 });
    fs.writeFileSync(markerPath, JSON.stringify({
      newVersion: '9.9.9',
      prevBinaryPath: prevPath,
      installedAt: Date.now() - 60_000,
    }));

    const spawns = []; const exits = [];
    const up = mkRollbackUpdater({
      currentVersion: '9.9.9',
      markerPath,
      execPath,
      spawnCapture: spawns,
      exitCapture: exits,
    });
    assert.equal(await up.checkRollback(), 'rolled-back');
    assert.equal(fs.readFileSync(execPath, 'utf8'), 'GOOD OLD');
    // b.selfUpdate.rollback uses copy semantics, but our wrapper unlinks
    // the .prev after a successful rollback so a subsequent boot doesn't
    // see the old marker pointing at a stale .prev.
    assert.equal(fs.existsSync(prevPath), false, 'prev should have been removed after rollback');
    assert.equal(fs.existsSync(markerPath), false);
    assert.equal(spawns.length, 1);
    assert.equal(spawns[0].cmd, execPath);
    assert.deepEqual(exits, [0]);
  });

  it('stale marker (version mismatch): clears marker without rollback', async () => {
    const dir = tempDir('rb');
    const markerPath = path.join(dir, 'update-pending.json');
    const execPath = path.join(dir, 'hs');
    fs.writeFileSync(execPath, 'current', { mode: 0o755 });
    fs.writeFileSync(markerPath, JSON.stringify({
      newVersion: '99.99.99',
      prevBinaryPath: path.join(dir, 'hs.prev'),
      installedAt: Date.now() - 60_000,
    }));

    const spawns = []; const exits = [];
    const up = mkRollbackUpdater({
      currentVersion: '0.4.6',
      markerPath,
      execPath,
      spawnCapture: spawns,
      exitCapture: exits,
    });
    assert.equal(await up.checkRollback(), 'stale-cleared');
    assert.equal(fs.existsSync(markerPath), false);
    assert.equal(spawns.length, 0);
  });

  it('rollback fails when .prev is missing: reports rollback-failed, does not exit', async () => {
    const dir = tempDir('rb');
    const markerPath = path.join(dir, 'update-pending.json');
    const execPath = path.join(dir, 'hs');
    fs.writeFileSync(execPath, 'current', { mode: 0o755 });
    fs.writeFileSync(markerPath, JSON.stringify({
      newVersion: '9.9.9',
      prevBinaryPath: path.join(dir, 'does-not-exist.prev'),
      installedAt: Date.now() - 60_000,
    }));

    const spawns = []; const exits = [];
    const up = mkRollbackUpdater({
      currentVersion: '9.9.9',
      markerPath,
      execPath,
      spawnCapture: spawns,
      exitCapture: exits,
    });
    assert.equal(await up.checkRollback(), 'rollback-failed');
    assert.equal(fs.existsSync(markerPath), false);
    assert.equal(spawns.length, 0);
    assert.equal(exits.length, 0);
  });
});

describe('Auto-update — helpers', () => {
  it('compareVersions: newer > older, equal = 0', () => {
    assert.equal(compareVersions('0.4.6', '0.4.5'), 1);
    assert.equal(compareVersions('0.4.5', '0.4.6'), -1);
    assert.equal(compareVersions('0.4.6', '0.4.6'), 0);
    assert.equal(compareVersions('1.0.0', '0.9.9'), 1);
    assert.equal(compareVersions('v0.4.6', '0.4.6'), 0);
    assert.equal(compareVersions('0.5.0', '0.4.99'), 1);
  });

  it('assetName embeds platform + arch + version', () => {
    const n = assetName('1.2.3');
    assert.ok(n.includes('-v1.2.3-'));
    assert.ok(n.includes(process.arch));
  });
});
